import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/app/news_list/widgets/news_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

void main() {
  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final List<CurrencyModel> currencyItems = [
      CurrencyModel(id: '1', nominal: 1, name: 'Доллар США', symbol: 'USD', value: 78.4181, previousValue: 78.5),
      CurrencyModel(id: '2', nominal: 1, name: 'Евро', symbol: 'EUR', value: 92.7440, previousValue: 92.2),
    ];

    final List<NewsModel> newsItems = [
      NewsModel(title: 'Свежая новость', link: 'https://example.com/fresh', date: DateTime(2025, 1, 1)),
    ];

    Widget dashboardWidget() => buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        );

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any))
          .thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => newsItems);
    });

    testWidgets('should show progress indicator while data is loading', (WidgetTester tester) async {
      final Completer<CurrencyPage> currencyCompleter = Completer<CurrencyPage>();
      final Completer<List<NewsModel>> newsCompleter = Completer<List<NewsModel>>();

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) => currencyCompleter.future);
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) => newsCompleter.future);

      await tester.pumpWidget(dashboardWidget());
      await tester.pump();

      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      currencyCompleter.complete(const CurrencyPage(items: [], page: 0, hasMore: false));
      newsCompleter.complete(const []);
      await tester.pumpAndSettle();

      expect(find.byType(CircularProgressIndicator), findsNothing);
    });

    testWidgets('should request fresh currency rate and news feed in parallel', (WidgetTester tester) async {
      await tester.pumpWidget(dashboardWidget());
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));
      expect(find.byType(NewsCard), findsNWidgets(newsItems.length));

      final CurrencyPageRequest currencyRequest = verify(mockCurrencyRepository.fetchRates(captureAny)).captured.single as CurrencyPageRequest;
      final NewsFeedFilter newsFilter = verify(mockNewsRepository.loadNewsFeed(captureAny)).captured.single as NewsFeedFilter;

      expect(currencyRequest.page, 0);
      expect(newsFilter.forceRefresh, isTrue);
    });
  });
}
